double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    // Zero gradients
    for (int i = 0; i < n_hidden * n_in + n_hidden + n_hidden + 1; ++i) {
        grad[i] = 0.0;
    }

    double total_loss = 0.0;

    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;
        double y_s = y[s];

        // Hidden layer activations
        double* h = new double[n_hidden];
        for (int j = 0; j < n_hidden; ++j) {
            double sum = params[j * n_in];  // b1[j]
            for (int k = 0; k < n_in; ++k) {
                sum += params[j * n_in + n_hidden + k] * x[k];  // W1[j][k]
            }
            h[j] = tanh(sum);
        }

        // Output
        double z = params[n_hidden * n_in + 2 * n_hidden];  // b2
        for (int j = 0; j < n_hidden; ++j) {
            z += params[n_hidden * n_in + n_hidden + j] * h[j];  // W2[j]
        }
        double p = 1.0 / (1.0 + exp(-z));

        // Loss for this sample
        double loss_s = -(y_s * log(p) + (1.0 - y_s) * log(1.0 - p));
        total_loss += loss_s;

        // Backprop
        double dz = p - y_s;  // dL/dz

        // Grad for b2
        grad[n_hidden * n_in + 2 * n_hidden] += dz;

        // Grad for W2 and b1, W1
        for (int j = 0; j < n_hidden; ++j) {
            // Grad for W2[j]
            grad[n_hidden * n_in + n_hidden + j] += dz * h[j];

            // Grad for b1[j] and W1[j][k]
            double dh = dz * params[n_hidden * n_in + n_hidden + j] * (1.0 - h[j] * h[j]);  // dL/dh * dh/dz_j
            grad[j * n_in] += dh;  // b1[j]
            for (int k = 0; k < n_in; ++k) {
                grad[j * n_in + n_hidden + k] += dh * x[k];  // W1[j][k]
            }
        }

        delete[] h;
    }

    // Average loss and gradients
    double avg_loss = total_loss / n_samples;
    for (int i = 0; i < n_hidden * n_in + n_hidden + n_hidden + 1; ++i) {
        grad[i] /= n_samples;
    }

    return avg_loss;
}

struct Tape {
    struct Node {
        double value;
        double grad;
        int op; // 0: constant, 1: input, 2: add, 3: mul, 4: sin_, 5: exp_
        int left, right; // for binary ops; for unary, left is child, right unused
    };
    std::vector<Node> nodes;

    int constant(double v) {
        nodes.push_back({v, 0.0, 0, -1, -1});
        return nodes.size() - 1;
    }

    int input(double v) {
        nodes.push_back({v, 0.0, 1, -1, -1});
        return nodes.size() - 1;
    }

    int add(int a, int b) {
        double va = nodes[a].value;
        double vb = nodes[b].value;
        nodes.push_back({va + vb, 0.0, 2, a, b});
        return nodes.size() - 1;
    }

    int mul(int a, int b) {
        double va = nodes[a].value;
        double vb = nodes[b].value;
        nodes.push_back({va * vb, 0.0, 3, a, b});
        return nodes.size() - 1;
    }

    int sin_(int a) {
        double va = nodes[a].value;
        nodes.push_back({std::sin(va), 0.0, 4, a, -1});
        return nodes.size() - 1;
    }

    int exp_(int a) {
        double va = nodes[a].value;
        nodes.push_back({std::exp(va), 0.0, 5, a, -1});
        return nodes.size() - 1;
    }

    double value(int node) const {
        return nodes[node].value;
    }

    void backward(int root) {
        // Initialize gradients
        for (auto& n : nodes) n.grad = 0.0;
        nodes[root].grad = 1.0;

        // Traverse in reverse order (recording order ensures consumers before inputs)
        for (int i = nodes.size() - 1; i >= 0; --i) {
            Node& n = nodes[i];
            double g = n.grad;
            if (g == 0.0) continue; // skip if no gradient to propagate
            switch (n.op) {
                case 2: // add
                    nodes[n.left].grad += g;
                    nodes[n.right].grad += g;
                    break;
                case 3: // mul
                    nodes[n.left].grad += g * nodes[n.right].value;
                    nodes[n.right].grad += g * nodes[n.left].value;
                    break;
                case 4: // sin_
                    nodes[n.left].grad += g * std::cos(nodes[n.left].value);
                    break;
                case 5: // exp_
                    nodes[n.left].grad += g * std::exp(nodes[n.left].value);
                    break;
                default: // constant or input: no propagation
                    break;
            }
        }
    }

    double grad(int node) const {
        return nodes[node].grad;
    }
};

