        } else {
            As[ty][tx] = 0.0f;
        }

        tiled_k = t * 16 + ty;
        if (col < N && tiled_k < K) {
            Bs[ty][tx] = B[tiled_k * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        for (int k = 0; k < 16; ++k) {
            sum += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}
